#include "TamperEvidentClinicalLog.h"
#include <functional>
namespace dnxr { namespace { std::string digest(const std::string& s){ return std::to_string(std::hash<std::string>{}(s)); } } ClinicalLogEntry TamperEvidentClinicalLog::append(const std::string& type,const std::string& payload,const std::string& utc){ ClinicalLogEntry e; e.sequence=entries_.size()+1U; e.utcTimestamp=utc; e.eventType=type; e.payloadHash=payload; e.previousHash=entries_.empty()?"GENESIS":entries_.back().entryHash; e.entryHash=digest(std::to_string(e.sequence)+e.utcTimestamp+e.eventType+e.payloadHash+e.previousHash); entries_.push_back(e); return e; } bool TamperEvidentClinicalLog::verify() const { std::string prev="GENESIS"; for(const auto& e:entries_){ if(e.previousHash!=prev) return false; if(e.entryHash!=digest(std::to_string(e.sequence)+e.utcTimestamp+e.eventType+e.payloadHash+e.previousHash)) return false; prev=e.entryHash; } return true; } const std::vector<ClinicalLogEntry>& TamperEvidentClinicalLog::entries() const { return entries_; } }
